/**
 * The page's host, read in one place: the PDF renderer's flag and the Uhuu SDK. Without a DOM
 * (server rendering, Node tests) there is no host.
 */

/** The PDF renderer sets `window.$uhuu_renderer`: nothing is interactive there. */
export function isRendererMode() {
  return typeof window !== 'undefined' && Boolean(window.$uhuu_renderer);
}

/** The Uhuu SDK (`window.$uhuu`), or `undefined` without one. */
export function uhuuHost() {
  return typeof window === 'undefined' ? undefined : window.$uhuu;
}

/** A preview host (Template Studio, a template's dev page) turned on the editor shell's dev tools. */
export function hostDevToolsEnabled() {
  return typeof window !== 'undefined' && Boolean(window.__uhuuPreviewHost?.enableEditorShellDevTools);
}
