/** The element scrolled on each axis when correcting a focal zoom. */
interface ScrollTargets {
  x: Element | null
  y: Element | null
}

/**
 * Pan-viewport geometry is applied inline rather than from `section-page-resizer.css`.
 *
 * These declarations are load-bearing, not cosmetic: without the pane's `height`/`overflow`
 * the element becomes a plain block that reports its entire content height, and fit-to-height
 * then divides by a viewport many times too tall. Consumers do not always end up with the
 * component stylesheet — Template Studio renders the editor in an iframe whose document never
 * received it — so correctness cannot depend on it. The matching CSS rules remain for styling
 * parity; inline styles win over them either way.
 */
const PANE_GUTTER_X = 24
const PANE_GUTTER_BOTTOM = 64

/** Upper bound on how long the initial fit may keep the sheets hidden. */
const INITIAL_FIT_REVEAL_TIMEOUT_MS = 1000

const PANE_CONTENT_STYLE: React.CSSProperties = {
  // Auto margins centre the stack while it fits and collapse to 0 once it overflows, which is
  // what keeps both edges reachable. Padding sits on the content box so `scrollWidth` counts
  // the right-hand gutter.
  width: "max-content",
  margin: "auto",
  padding: `0 ${PANE_GUTTER_X}px ${PANE_GUTTER_BOTTOM}px`,
  overflowAnchor: "none",
}

/**
 * A toolbar at the top keeps the first sheet's controls clear instead of the last sheet's: the
 * gutter moves to the top, and the vertical total (what fit divides by) stays the same.
 */
const PANE_CONTENT_STYLE_TOOLBAR_TOP: React.CSSProperties = {
  ...PANE_CONTENT_STYLE,
  padding: `${PANE_GUTTER_BOTTOM}px ${PANE_GUTTER_X}px 0`,
}

// The marker inside each corner of the zoom menu's position picker.
const TOOLBAR_MARKER_CLASS: Record<ToolbarPosition, string> = {
  "bottom-right": "uhuu:right-0.5 uhuu:bottom-0.5",
  "bottom-left": "uhuu:left-0.5 uhuu:bottom-0.5",
  "top-right": "uhuu:right-0.5 uhuu:top-0.5",
  "top-left": "uhuu:left-0.5 uhuu:top-0.5",
}

const TOOLBAR_POSITION_LABEL = {
  "bottom-right": "toolbar.bottomRight",
  "bottom-left": "toolbar.bottomLeft",
  "top-right": "toolbar.topRight",
  "top-left": "toolbar.topLeft",
} as const satisfies Record<ToolbarPosition, string>

/**
 * Resolve the scroller per axis, keyed off declared overflow.
 *
 * Only used in `scrollMode="document"`. Testing `scrollHeight > clientHeight` instead would
 * skip an `overflow: auto` ancestor that is not scrollable *yet* but becomes the scroller as
 * soon as zoom grows the content — sending the correction to the wrong element. Axes resolve
 * independently because a host may scroll X and Y on different ancestors.
 */
function resolveScrollTargets(from: HTMLElement | null): ScrollTargets {
  let node: HTMLElement | null = from
  let x: Element | null = null
  let y: Element | null = null
  while (node && node !== document.documentElement) {
    const style = window.getComputedStyle(node)
    if (!x && isScrollableOverflow(style.overflowX)) x = node
    if (!y && isScrollableOverflow(style.overflowY)) y = node
    if (x && y) return { x, y }
    node = node.parentElement
  }
  const root = document.scrollingElement
  return { x: x ?? root, y: y ?? root }
}

/**
 * Vertical space the host reserves around the editor, so the pane can fill exactly the rest
 * of the viewport.
 *
 * The top inset is just the container's offset. The bottom inset has to be summed from the
 * ancestors' own bottom insets rather than measured directly: a host sized with `h-full`
 * against an auto-height root (Storybook's fullscreen wrapper) is circular — its height is
 * whatever the pane makes it — so reading its box would just echo the pane back. Padding and
 * borders, unlike heights, are stable under that loop, which makes this converge.
 */
function measureHostInset(container: HTMLElement): number {
  const top = Math.max(container.getBoundingClientRect().top, 0)
  let bottom = 0
  let node: HTMLElement | null = container.parentElement
  while (node && node !== document.documentElement) {
    const style = window.getComputedStyle(node)
    if (style.display !== "contents") {
      bottom +=
        (Number.parseFloat(style.paddingBottom) || 0) +
        (Number.parseFloat(style.borderBottomWidth) || 0) +
        Math.max(Number.parseFloat(style.marginBottom) || 0, 0)
    }
    node = node.parentElement
  }
  return top + bottom
}

/**
 * Vertical space `Section` adds around the scaled sheet (header + reserved spacer).
 *
 * Both heights are read from rendered rects — the sheet's rect already includes its
 * `scale()` — so this never needs the current zoom. Deriving the scaled height from state
 * instead would read a zoom that the ResizeObserver/rAF path can observe before React's
 * passive effects have committed it, making the subtraction go negative and silently
 * report zero chrome.
 */
function measureSectionChrome(content: HTMLElement): number {
  const section = content.querySelector("[data-section-content]")
  const wrapper = section?.closest<HTMLElement>('[class*="group/section"]')
  if (!section || !wrapper) return 0
  const scaledSheetHeight = section.getBoundingClientRect().height
  if (!(scaledSheetHeight > 0)) return 0
  return Math.max(wrapper.getBoundingClientRect().height - scaledSheetHeight, 0)
}

// Context for sharing zoom state across all sections
interface ZoomContextType {
  zoom: number
  scaleValue: number
  hideUI: boolean
}

const ZoomContext = createContext<ZoomContextType>({ zoom: 100, scaleValue: 1, hideUI: false })

interface SectionPageResizerProps {
  children: React.ReactNode
  className?: string
  defaultZoom?: number
  minZoom?: number
  maxZoom?: number
  onAddPage?: () => void
  menuItems?: React.ReactNode
  hideUI?: boolean
  preview?: PreviewMode
  /** Initial fit preference. Subsequent prop changes do not override user zoom input. */
  defaultZoomMode?: DefaultZoomMode
  /**
   * The corner the floating toolbar starts in (default bottom right). A user moves it from the
   * zoom menu; their corner is remembered in the browser and wins over this one.
   */
  toolbarPosition?: ToolbarPosition
  /**
   * Where the editor scrolls. `"pane"` (default) gives the editor its own pan viewport so a
   * zoomed-in page is reachable on both axes. `"document"` restores the legacy behavior of
   * riding the nearest ancestor scroller — use it when the host already provides one.
   */
  scrollMode?: ScrollMode
}

export type PreviewMode = "single_page" | "two_pages"
export type DefaultZoomMode = "manual" | "fit-width" | "fit-height" | "fit-page"
export type ScrollMode = "pane" | "document"

interface TwoPageSectionProps {
  children: React.ReactNode
  /** "spread" = two pages side by side, "left" = single page on left, "right" = single page on right */
  layout?: "spread" | "left" | "right"
  pageItemId?: string
}

export function TwoPageSection({ children, layout = "spread", pageItemId }: TwoPageSectionProps) {
  const { scaleValue } = useContext(ZoomContext)
  const pairRef = useRef<HTMLDivElement>(null)

  // Update pair width based on scaled content dimensions
  useEffect(() => {
    if (!pairRef.current) return

    const updatePairWidth = () => {
      const sections = pairRef.current?.querySelectorAll('[data-section-content]')
      if (!sections?.length) return

      // Sum natural widths of all pages in this pair
      const totalNaturalWidth = Array.from(sections).reduce((sum, section) => {
        const width = Number.parseInt(section.getAttribute('data-natural-width') || '0')
        return sum + width
      }, 0)

      if (totalNaturalWidth > 0) {
        const scaledWidth = totalNaturalWidth * scaleValue
        pairRef.current?.style.setProperty('--uhuu-group-pair-width', `${scaledWidth}px`)
      }
    }

    updatePairWidth()

    const resizeObserver = new ResizeObserver(updatePairWidth)
    const sections = pairRef.current.querySelectorAll('[data-section-content]')
    sections.forEach((section) => resizeObserver.observe(section))

    return () => resizeObserver.disconnect()
  }, [children, scaleValue])

  return (
    <div
      ref={pairRef}
      className={`two-pages-pair two-pages-pair--${layout}`}
      data-page-item-id={pageItemId}
    >
      {children}
    </div>
  )
}

interface SectionProps {
  children: React.ReactNode
  title: string
  className?: string
  controls?: React.ReactNode
  origin?: "left" | "right" | "center"
}

type FitMode = "none" | "width" | "height" | "both"

type FitDimensions = { width: number; height: number }

function naturalDimensions(section: Element): FitDimensions | null {
  const width = Number.parseFloat(section.getAttribute("data-natural-width") || "0")
  const height = Number.parseFloat(section.getAttribute("data-natural-height") || "0")
  return width > 0 && height > 0 ? { width, height } : null
}

/**
 * Fit targets the visible unit users expect on load:
 * - facing mode → first `.two-pages-pair`
 * - single-page mode → first sheet only (not the sum of every stacked page)
 */
function getFitDimensions(content: HTMLElement, preview: PreviewMode): FitDimensions | null {
  const scope = preview === "two_pages"
    ? content.querySelector(".two-pages-pair")
    : content
  if (!scope) return null

  const sections = preview === "two_pages"
    ? Array.from(scope.querySelectorAll("[data-section-content]"))
    : (() => {
        const first = scope.querySelector("[data-section-content]")
        return first ? [first] : []
      })()
  if (!sections.length) return null

  const dimensions = sections
    .map(naturalDimensions)
    .filter((value): value is FitDimensions => value !== null)
  return resolveFitUnitDimensions(preview, dimensions)
}

// Individual Section Component
export function Section({ children, title, className = "", controls, origin = "center" }: SectionProps) {
  const { scaleValue, hideUI } = useContext(ZoomContext)
  const contentRef = useRef<HTMLDivElement>(null)
  const [contentHeight, setContentHeight] = useState<number>(0)
  const [contentWidth, setContentWidth] = useState<number>(0)

  // Calculate and update content dimensions
  useEffect(() => {
    if (contentRef.current) {
      const updateDimensions = () => {
        const element = contentRef.current
        if (element) {
          // scroll dimensions are in layout space; CSS transforms never change them. Reading
          // directly avoids two style invalidations and a forced layout for every section.
          const naturalHeight = element.scrollHeight
          const naturalWidth = element.scrollWidth

          setContentHeight(naturalHeight)
          setContentWidth(naturalWidth)
        }
      }

      updateDimensions()

      const resizeObserver = new ResizeObserver(updateDimensions)
      resizeObserver.observe(contentRef.current)

      return () => {
        resizeObserver.disconnect()
      }
    }
  }, [children])

  const scaledHeight = contentHeight * scaleValue
  const scaledWidth = Math.max(contentWidth * scaleValue, 150)
  
  // Align content based on transform origin (left/right for spreads, center for single pages)
  const alignmentMap = {
    left: { justify: "uhuu:justify-start", origin: "top left" },
    right: { justify: "uhuu:justify-end", origin: "top right" },
    center: { justify: "uhuu:justify-center", origin: "top center" },
  }
  const { justify: contentAlignClass, origin: transformOrigin } = alignmentMap[origin]

  // If hiding UI, render children directly without controls or scaling
  if (hideUI) {
    return <div className={className}>{children}</div>
  }

  return (
    <div 
      className={`uhuu:group/section ${className}`}
      style={{
        width: `${scaledWidth}px`,
        minWidth: "150px",
      }}
    >
      {/* Section Header */}
      <div>
        {controls ?? (
          <div data-uhuu-editor className="uhuu:px-4 uhuu:py-2 uhuu:border-b uhuu:border-gray-200">
            <div className="uhuu:text-sm uhuu:font-medium uhuu:text-gray-700">{title} Controls</div>
          </div>
        )}
      </div>

      {/* Section Content - Scaled with dynamic height */}
      <div
        className="uhuu:pt-1"
        style={{
          height: scaledHeight > 0 ? `${scaledHeight + 32}px` : "auto",
          minHeight: "100px",
        }}
      >
        <div className={`uhuu:flex uhuu:items-start ${contentAlignClass}`}>
          <div
            ref={contentRef}
            data-section-content
            data-natural-width={contentWidth}
            data-natural-height={contentHeight}
            style={{
              // Preserve CSSOM's former six-significant-digit scale roundtrip without DOM writes.
              transform: `scale(${Number(scaleValue.toPrecision(6))})`,
              transformOrigin,
            }}
          >
            {children}
          </div>
        </div>
      </div>
    </div>
  )
}

// Main Container with Controls
export default function SectionPageResizer({
  children,
  className = "",
  defaultZoom = 100,
  minZoom = 25,
  maxZoom = 200,
  onAddPage,
  menuItems,
  hideUI: hideUIProp,
  preview = "single_page",
  defaultZoomMode = "manual",
  scrollMode = "pane",
  toolbarPosition: initialToolbarPosition,
}: SectionPageResizerProps) {
  const shouldHideUI = useShouldHideUI()
  const hideUI = hideUIProp ?? shouldHideUI
  const { t } = useShellTranslation()
  const toolbarSlotRef = useToolbarSlotRef()
  const [toolbarPosition, setToolbarPosition] = useToolbarPosition(initialToolbarPosition)
  const menuPlacement = toolbarMenuPlacement(toolbarPosition)
  const toolbarPositionLabelId = React.useId()

  const [zoom, setZoom] = useState(defaultZoom)
  const [fitMode, setFitMode] = useState<FitMode>(() => fitModeFromDefaultZoomMode(defaultZoomMode))
  /**
   * Whether the sheets are still waiting for the *initial* fit.
   *
   * A starting fit mode cannot resolve during the first commit: `Section` publishes its natural
   * size from an effect, so the sheets are unmeasured until a later frame and fit has nothing to
   * divide by. Painting `defaultZoom` in the meantime shows a wrong — usually cropped — page for
   * a frame or two before it snaps to the fitted size. Holding the stack at `visibility: hidden`
   * (which still lays out, so the measurements fit depends on keep arriving) until the first fit
   * lands makes the document open at its fitted zoom instead of flashing.
   */
  const [awaitingInitialFit, setAwaitingInitialFit] = useState(
    () => fitModeFromDefaultZoomMode(defaultZoomMode) !== "none",
  )
  const [paneInset, setPaneInset] = useState(0)
  const containerRef = useRef<HTMLDivElement>(null)
  const paneRef = useRef<HTMLDivElement>(null)
  const paneContentRef = useRef<HTMLDivElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const zoomRef = useRef(zoom)

  useEffect(() => {
    zoomRef.current = zoom
  }, [zoom])

  /** The scrollers the focal correction drives. In pane mode both axes are the pane itself. */
  const resolveScrollers = useCallback((): ScrollTargets => {
    if (scrollMode === "pane" && paneRef.current) {
      return { x: paneRef.current, y: paneRef.current }
    }
    return resolveScrollTargets(containerRef.current)
  }, [scrollMode])

  /**
   * Single entry point for every zoom change — wheel, ± buttons and the % input all route
   * here so the content point at (focalClientX, focalClientY) stays put. Previously only the
   * wheel path corrected scroll, so the toolbar controls drifted the viewport.
   */
  const applyZoom = useCallback((nextZoom: number, focalClientX: number, focalClientY: number) => {
    const clamped = Math.min(Math.max(nextZoom, minZoom), maxZoom)
    const content = contentRef.current
    if (!content) {
      setZoom(clamped)
      setFitMode("none")
      return
    }

    const scrollers = resolveScrollers()
    // Anchor on the sheet under the pointer, not the whole stack: only the sheet is uniformly
    // scaled, so mapping a point by the before/after rect ratio is exact for it.
    const sheets = Array.from(content.querySelectorAll<HTMLElement>("[data-section-content]"))
    const anchorIndex = pickZoomFocalAnchor(
      sheets.map((sheet) => snapshotZoomFocalRect(sheet.getBoundingClientRect())),
      focalClientX,
      focalClientY,
    )
    const anchor: HTMLElement = anchorIndex >= 0 ? sheets[anchorIndex] : content

    const before = snapshotZoomFocalRect(anchor.getBoundingClientRect())
    const focal = resolveZoomFocalPoint(before, focalClientX, focalClientY)

    // flushSync so section layout heights commit before we measure the post-zoom rect.
    flushSync(() => {
      setZoom(clamped)
      setFitMode("none")
    })

    // Re-measuring `after` each pass makes this idempotent: once the point is anchored the
    // delta is zero, so the follow-up frame only catches layout that settled late.
    const correct = () => {
      const after = snapshotZoomFocalRect(anchor.getBoundingClientRect())
      const { deltaLeft, deltaTop } = zoomFocalScrollDelta(before, after, focal.clientX, focal.clientY)
      if (deltaLeft !== 0 && scrollers.x) scrollers.x.scrollLeft += deltaLeft
      if (deltaTop !== 0 && scrollers.y) scrollers.y.scrollTop += deltaTop
    }
    correct()
    window.requestAnimationFrame(correct)
  }, [maxZoom, minZoom, resolveScrollers])

  /** Toolbar zoom anchors on the middle of the visible pane. */
  const viewportFocalPoint = useCallback(() => {
    const host = (scrollMode === "pane" ? paneRef.current : containerRef.current)
    const rect = host?.getBoundingClientRect()
    if (!rect) return { clientX: 0, clientY: 0 }
    return { clientX: rect.left + rect.width / 2, clientY: rect.top + rect.height / 2 }
  }, [scrollMode])

  const recalculateFit = useCallback(() => {
    const content = contentRef.current
    if (fitMode === "none" || !content) return

    const dimensions = getFitDimensions(content, preview)
    if (!dimensions) return

    // Measure the pane the sheets actually live in, and read the gutters off the rendered
    // content box, so fit stays exact instead of guessing fixed insets.
    const pane = scrollMode === "pane" ? paneRef.current : containerRef.current
    if (!pane) return
    const paneBox = pane.getBoundingClientRect()
    // Measure against the pane's own document: the editor is often iframed, and the host
    // window's viewport says nothing about the space the sheets actually have.
    const paneView = pane.ownerDocument.defaultView ?? window
    const viewportHeight =
      paneView.visualViewport?.height
      ?? pane.ownerDocument.documentElement.clientHeight
      ?? paneView.innerHeight
    const paneWidth = pane.clientWidth || paneBox.width
    // In document mode the container is as tall as its content, so fall back to the viewport.
    const paneHeight = scrollMode === "pane"
      ? resolveFitPaneHeight({
          paneClientHeight: pane.clientHeight || paneBox.height,
          paneTop: paneBox.top,
          viewportHeight,
        })
      : viewportHeight - Math.max(paneBox.top, 0)

    const paneContentStyle = paneContentRef.current ? window.getComputedStyle(paneContentRef.current) : null
    const paddingX = paneContentStyle
      ? Number.parseFloat(paneContentStyle.paddingLeft) + Number.parseFloat(paneContentStyle.paddingRight)
      : 0
    const paddingY = paneContentStyle
      ? Number.parseFloat(paneContentStyle.paddingTop) + Number.parseFloat(paneContentStyle.paddingBottom)
      : 0

    const { availableWidth, availableHeight } = resolveFitAvailableSpace({
      paneWidth,
      paneHeight,
      paddingX,
      paddingY,
      chromeHeight: measureSectionChrome(content),
    })

    const nextZoom = calculateFitZoom({
      mode: fitMode,
      contentWidth: dimensions.width,
      contentHeight: dimensions.height,
      availableWidth,
      availableHeight,
      minZoom,
      maxZoom,
    })

    if (nextZoom === null) return
    setZoom((currentZoom) => Math.abs(currentZoom - nextZoom) < 0.01 ? currentZoom : nextZoom)
    setAwaitingInitialFit(false)
  }, [fitMode, maxZoom, minZoom, preview, scrollMode])

  // Handle fit mode changes
  const handleFitMode = (mode: FitMode) => {
    setFitMode(mode)
  }

  // Never let a fit that cannot resolve hide the document: reveal on the next macrotask if the
  // sheets are still unmeasured (an empty editor, or a host that renders it detached), and as
  // soon as any manual zoom clears fit mode.
  useEffect(() => {
    if (!awaitingInitialFit) return
    if (fitMode === "none") {
      setAwaitingInitialFit(false)
      return
    }
    const timer = window.setTimeout(() => setAwaitingInitialFit(false), INITIAL_FIT_REVEAL_TIMEOUT_MS)
    return () => window.clearTimeout(timer)
  }, [awaitingInitialFit, fitMode])

  // Zoom in/out buttons with 25% steps
  const zoomIn = () => {
    const focal = viewportFocalPoint()
    applyZoom(zoom + 25, focal.clientX, focal.clientY)
  }

  const zoomOut = () => {
    const focal = viewportFocalPoint()
    applyZoom(zoom - 25, focal.clientX, focal.clientY)
  }

  // Fit starts as soon as dimensions exist, then follows the active document's
  // viewport and natural sheet size until a manual zoom choice clears fitMode.
  useEffect(() => {
    if (fitMode === "none" || !containerRef.current || !contentRef.current) return

    let frame = 0
    const scheduleFit = () => {
      window.cancelAnimationFrame(frame)
      frame = window.requestAnimationFrame(recalculateFit)
    }
    const resizeObserver = new ResizeObserver(scheduleFit)
    resizeObserver.observe(containerRef.current)
    if (paneRef.current) resizeObserver.observe(paneRef.current)
    // The content stack has to be observed explicitly: sheets report their natural size a
    // frame after mount, and in pane mode the container/pane are fixed height, so neither
    // resizes when that measurement lands. Without this, fit never runs on first paint.
    resizeObserver.observe(contentRef.current)
    const observeSections = () => {
      contentRef.current?.querySelectorAll("[data-section-content]").forEach((section) => {
        resizeObserver.observe(section)
      })
    }
    observeSections()
    const mutationObserver = new MutationObserver(() => {
      observeSections()
      scheduleFit()
    })
    mutationObserver.observe(contentRef.current, { childList: true, subtree: true })

    window.addEventListener("resize", scheduleFit)
    window.visualViewport?.addEventListener("resize", scheduleFit)
    scheduleFit()
    return () => {
      window.cancelAnimationFrame(frame)
      resizeObserver.disconnect()
      mutationObserver.disconnect()
      window.removeEventListener("resize", scheduleFit)
      window.visualViewport?.removeEventListener("resize", scheduleFit)
    }
  }, [fitMode, recalculateFit])

  // The pane fills the viewport minus whatever the host reserves above and below it, so the
  // editor never pushes a second (document-level) scrollbar behind its own.
  useEffect(() => {
    if (hideUI || scrollMode !== "pane") return
    const container = containerRef.current
    if (!container) return

    const syncPaneInset = () => {
      const inset = measureHostInset(container)
      setPaneInset((current) => (Math.abs(current - inset) < 0.5 ? current : inset))
    }

    syncPaneInset()
    const resizeObserver = new ResizeObserver(syncPaneInset)
    resizeObserver.observe(container)
    window.addEventListener("resize", syncPaneInset)
    window.visualViewport?.addEventListener("resize", syncPaneInset)
    return () => {
      resizeObserver.disconnect()
      window.removeEventListener("resize", syncPaneInset)
      window.visualViewport?.removeEventListener("resize", syncPaneInset)
    }
  }, [hideUI, scrollMode])

  // Ctrl/Cmd-wheel and trackpad pinch (wheel + ctrlKey) zoom; plain wheel still scrolls the pane.
  // Match Design canvas: proportional ~0.3%/px, rAF-batched, clears fit mode, zoom-to-cursor.
  useEffect(() => {
    if (hideUI) return

    let zoomFrameId: number | null = null
    let attachFrameId: number | null = null
    let pendingZoom: number | null = null
    let pendingFocal = { clientX: 0, clientY: 0 }
    let target: HTMLDivElement | null = null
    let cancelled = false

    const applyPendingZoom = () => {
      zoomFrameId = null
      const next = pendingZoom
      pendingZoom = null
      if (next === null) return
      applyZoom(next, pendingFocal.clientX, pendingFocal.clientY)
    }

    const handleWheel = (event: WheelEvent) => {
      if (!event.ctrlKey && !event.metaKey) return
      event.preventDefault()

      const lineSize = 16
      const pixelDelta =
        event.deltaMode === 1 ? event.deltaY * lineSize :
        event.deltaMode === 2 ? event.deltaY * lineSize * 32 :
        event.deltaY
      const base = pendingZoom ?? zoomRef.current
      const next = Math.min(Math.max(base * Math.pow(1.003, -pixelDelta), minZoom), maxZoom)
      pendingFocal = { clientX: event.clientX, clientY: event.clientY }
      if (next === base && pendingZoom === null) return
      pendingZoom = next
      if (zoomFrameId === null) zoomFrameId = window.requestAnimationFrame(applyPendingZoom)
    }

    const attach = () => {
      attachFrameId = null
      if (cancelled) return
      target = (scrollMode === "pane" ? paneRef.current : containerRef.current)
      if (!target) {
        attachFrameId = window.requestAnimationFrame(attach)
        return
      }
      target.addEventListener("wheel", handleWheel, { passive: false })
    }
    attach()

    return () => {
      cancelled = true
      if (zoomFrameId !== null) window.cancelAnimationFrame(zoomFrameId)
      if (attachFrameId !== null) window.cancelAnimationFrame(attachFrameId)
      target?.removeEventListener("wheel", handleWheel)
    }
  }, [applyZoom, hideUI, maxZoom, minZoom, scrollMode])

  const scaleValue = zoom / 100

  // If hiding UI, render children directly without any wrapper or controls
  if (hideUI) {
    return (
      <ZoomContext.Provider value={{ zoom: 100, scaleValue: 1, hideUI: true }}>
        <div className={className}>{children}</div>
      </ZoomContext.Provider>
    )
  }

  return (
    <ZoomContext.Provider value={{ zoom, scaleValue, hideUI: false }}>
      {/* `flex-1 min-h-0` so a host that is itself a flex column hands the editor a definite
          height — that is what lets the pane's `max-height: 100%` clamp to the host box
          (including its padding) instead of overflowing it by the bottom inset. Inert when
          the host is a plain block, where the pane falls back to viewport height. */}
      <div ref={containerRef} className={`uhuu:flex uhuu:flex-col uhuu:flex-1 uhuu:min-h-0 ${className}`}>
        {/* Global Controls - Unscaled */}
        <div
          data-uhuu-editor
          data-uhuu-toolbar-position={toolbarPosition}
          className={`uhuu:fixed ${TOOLBAR_CORNER_CLASS[toolbarPosition]} uhuu:z-50 uhuu:flex uhuu:items-center uhuu:gap-1.5 uhuu:px-2.5 uhuu:py-1.5 uhuu:bg-(--uhuu-shell-surface)/90 uhuu:backdrop-blur-md uhuu:border uhuu:border-gray-200/60 uhuu:rounded-lg uhuu:shadow-sm`}
        >
          <ToolbarPlacementProvider value={menuPlacement}>
          {menuItems}
          {/* Shell controls rendered outside PageEditor (DocumentOptions) join the toolbar here,
              beside `menuItems`, so a template that replaces the default menu keeps them. */}
          <div ref={toolbarSlotRef} className="uhuu:contents" />
          <div className="uhuu:h-4 uhuu:w-px uhuu:bg-gray-200 uhuu:mx-0.5" />
          <DropdownMenu modal={false}>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" title={t('zoom.menu')} className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-700 uhuu:hover:bg-gray-100/80 uhuu:h-7 uhuu:px-2.5">
                {Math.round(zoom)}%
                <ChevronDown className="uhuu:w-3 uhuu:h-3 uhuu:ml-1 uhuu:opacity-60" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="uhuu:w-52 uhuu:p-1.5" side={menuPlacement.side} align={menuPlacement.align}>
              <DropdownMenuItem
                onClick={() => handleFitMode("width")}
                className={`uhuu:cursor-pointer uhuu:flex uhuu:items-center ${fitMode === "width" ? "uhuu:bg-gray-100" : ""}`}
              >
                <UnfoldHorizontal className="uhuu:w-4 uhuu:h-4 uhuu:mr-2" />
                <span>{t('zoom.fitWidth')}</span>
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => handleFitMode("height")}
                className={`uhuu:cursor-pointer uhuu:flex uhuu:items-center ${fitMode === "height" ? "uhuu:bg-gray-100" : ""}`}
              >
                <UnfoldVertical className="uhuu:w-4 uhuu:h-4 uhuu:mr-2" />
                <span>{t('zoom.fitHeight')}</span>
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => handleFitMode("both")}
                className={`uhuu:cursor-pointer uhuu:flex uhuu:items-center ${fitMode === "both" ? "uhuu:bg-gray-100" : ""}`}
              >
                <Maximize className="uhuu:w-4 uhuu:h-4 uhuu:mr-2" />
                <span>{t('zoom.fitPage')}</span>
              </DropdownMenuItem>
              <DropdownMenuSeparator className="uhuu:my-1.5" />
              
              {/* Zoom Controls - Compact inline layout */}
              <div className="uhuu:flex uhuu:items-center uhuu:justify-center uhuu:gap-2 uhuu:px-3 uhuu:py-2.5" onClick={(e) => e.stopPropagation()}>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={(e) => {
                    e.stopPropagation()
                    zoomOut()
                  }}
                  disabled={zoom <= minZoom}
                  className="uhuu:h-8 uhuu:w-8 uhuu:p-0 uhuu:hover:bg-gray-100 uhuu:disabled:opacity-40"
                  title={t('zoom.zoomOut')}
                >
                  <ZoomOut className="uhuu:w-4 uhuu:h-4" />
                </Button>
                
                <div className="uhuu:relative">
                  <input
                    type="number"
                    value={Math.round(zoom)}
                    onChange={(e) => {
                      const value = Number.parseInt(e.target.value)
                      if (!isNaN(value)) {
                        const focal = viewportFocalPoint()
                        applyZoom(value, focal.clientX, focal.clientY)
                      }
                    }}
                    onFocus={(e) => e.target.select()}
                    className="uhuu:w-20 uhuu:pr-6 uhuu:text-center uhuu:text-sm uhuu:text-gray-700 uhuu:bg-(--uhuu-shell-surface) uhuu:border uhuu:border-gray-300 uhuu:rounded uhuu:px-2 uhuu:py-1.5 uhuu:focus:outline-none uhuu:focus:ring-2 uhuu:focus:ring-blue-500 uhuu:focus:border-transparent uhuu:transition-all"
                    min={minZoom}
                    max={maxZoom}
                  />
                  <span className="uhuu:absolute uhuu:right-2 uhuu:top-1/2 uhuu:-translate-y-1/2 uhuu:text-xs uhuu:text-gray-400 uhuu:pointer-events-none">%</span>
                </div>
                
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={(e) => {
                    e.stopPropagation()
                    zoomIn()
                  }}
                  disabled={zoom >= maxZoom}
                  className="uhuu:h-8 uhuu:w-8 uhuu:p-0 uhuu:hover:bg-gray-100 uhuu:disabled:opacity-40"
                  title={t('zoom.zoomIn')}
                >
                  <ZoomIn className="uhuu:w-4 uhuu:h-4" />
                </Button>
              </div>
              <DropdownMenuSeparator className="uhuu:my-1.5" />

              {/* Toolbar position: a 2 × 2 picker of the corners, each drawn as a page with the
                  toolbar's marker in that corner. Picking one closes the menu. */}
              <div className="uhuu:flex uhuu:items-center uhuu:justify-between uhuu:gap-3 uhuu:px-2 uhuu:py-1.5">
                <span id={toolbarPositionLabelId} className="uhuu:text-xs uhuu:text-gray-500">{t('toolbar.position')}</span>
                <DropdownMenuPrimitive.RadioGroup
                  aria-labelledby={toolbarPositionLabelId}
                  value={toolbarPosition}
                  onValueChange={(value) => setToolbarPosition(value as ToolbarPosition)}
                  className="uhuu:grid uhuu:grid-cols-2 uhuu:gap-1"
                >
                  {TOOLBAR_POSITIONS.map((position) => (
                    <DropdownMenuPrimitive.RadioItem
                      key={position}
                      value={position}
                      aria-label={t(TOOLBAR_POSITION_LABEL[position])}
                      title={t(TOOLBAR_POSITION_LABEL[position])}
                      className="uhuu:group/corner uhuu:relative uhuu:h-6 uhuu:w-8 uhuu:cursor-pointer uhuu:rounded uhuu:border uhuu:border-gray-200 uhuu:outline-none uhuu:transition-colors uhuu:hover:border-gray-400 uhuu:focus-visible:ring-2 uhuu:focus-visible:ring-gray-300 uhuu:data-[highlighted]:border-gray-400 uhuu:data-[state=checked]:border-gray-900 uhuu:data-[state=checked]:bg-gray-100"
                    >
                      <span
                        aria-hidden="true"
                        className={`uhuu:absolute ${TOOLBAR_MARKER_CLASS[position]} uhuu:h-1.5 uhuu:w-3 uhuu:rounded-[2px] uhuu:bg-gray-300 uhuu:transition-colors uhuu:group-hover/corner:bg-gray-500 uhuu:group-data-[state=checked]/corner:bg-gray-900`}
                      />
                    </DropdownMenuPrimitive.RadioItem>
                  ))}
                </DropdownMenuPrimitive.RadioGroup>
              </div>
            </DropdownMenuContent>
          </DropdownMenu>
          </ToolbarPlacementProvider>
        </div>

        {/* Pan viewport. Owning the scroller is what makes a zoomed-in page reachable on
            both axes — centering against the document split overflow to both sides and
            `scrollLeft` cannot go negative, so the left half was unreachable. */}
        <div
          ref={paneRef}
          className={scrollMode === "pane" ? "uhuu-zoom-pane" : undefined}
          style={scrollMode === "pane" ? {
            height: `calc(100dvh - ${paneInset}px)`,
            maxHeight: "100%",
            overflow: "auto",
            overscrollBehavior: "contain",
          } : undefined}
        >
          <div
            ref={paneContentRef}
            className="uhuu-zoom-pane-content"
            style={{
              ...(toolbarPosition.startsWith("top") ? PANE_CONTENT_STYLE_TOOLBAR_TOP : PANE_CONTENT_STYLE),
              ...(awaitingInitialFit ? { visibility: "hidden" as const } : null),
            }}
          >
            <div ref={contentRef} className={preview === "two_pages" ? "group_two_pages" : "uhuu:flex uhuu:flex-col uhuu:items-center"}>
              {children}
            </div>
          </div>
        </div>
      </div>
    </ZoomContext.Provider>
  )
}
