import { getTotalPageCount, type PageItem, type StandalonePage, type PageGroup } from './page-group-utils';
import { carrySavedSettings, type ResolvedPageManagement } from './page-management';
import { isTemplateLabel, type LocalizedText } from '../../i18n/i18n-core.js';
import type { BuildPageGroupsConfigArgs } from './page-group-presets';
import { enforcePageItemPositions, resolvePageComponentKeys, reportPageComponentKeysIssue } from './page-items-core';

type RestoreArgs = {
  initialItems: PageItem[];
  savedItems?: PageItem[];
  config: Pick<BuildPageGroupsConfigArgs, 'groups' | 'pages'>;
  payload: unknown;
  management: Pick<ResolvedPageManagement, 'templateOwnsPages' | 'rename'>;
};

/** Rehydrate saved layouts while keeping user additions, removals and names. No React or DOM. */
export function restorePageEditorItems({ initialItems, savedItems, config, payload, management }: RestoreArgs): PageItem[] {
  if (management.templateOwnsPages) return carrySavedSettings(initialItems, savedItems, { rename: management.rename });
  if (!savedItems) return initialItems;
  const rawGroups = config.groups ?? {};
  const groupDefs = Array.isArray(rawGroups) ? rawGroups : Object.entries(rawGroups).map(([id, group]) => ({ ...group, id }));
  const groupDefMap = new Map(groupDefs.map((group) => [group.id, group]));
  const pagesConfig = config.pages ?? {};
  const findPageTemplate = (page: Pick<StandalonePage, 'id' | 'componentKey' | 'templateId'>) =>
    pagesConfig[page.componentKey ?? page.templateId ?? page.id]
      ?? (page.templateId ? pagesConfig[page.templateId] : undefined) ?? pagesConfig[page.id];
  const applyPageTemplateMetadata = <Page extends Pick<StandalonePage, 'id' | 'componentKey' | 'templateId' | 'hasFlow'>>(page: Page): Page =>
    findPageTemplate(page)?.hasFlow && !page.hasFlow ? { ...page, hasFlow: true } : page;
  const withTemplateLabel = <Item extends { label?: LocalizedText }>(item: Item, label?: LocalizedText): Item =>
    label !== undefined && isTemplateLabel(item.label, label) && item.label !== label ? { ...item, label } : item;

  const rehydrated = savedItems.map((item): PageItem => {
    if (item.kind !== 'group') return withTemplateLabel(applyPageTemplateMetadata(item), findPageTemplate(item)?.label);
    const definition = groupDefMap.get(item.templateId ?? item.id);
    const labeled = withTemplateLabel(item, definition?.label);
    const baseGroup: PageGroup = {
      ...labeled,
      ...(definition?.strictPosition !== undefined && !labeled.strictPosition ? { strictPosition: definition.strictPosition } : {}),
      pages: labeled.pages.map(applyPageTemplateMetadata),
    };
    if (typeof definition?.pageComponentKeys !== 'function') return baseGroup;
    const result = resolvePageComponentKeys(definition.pageComponentKeys, { payload, item: undefined, parent: undefined });
    reportPageComponentKeysIssue(result.issue, item.templateId ?? item.id);
    if (result.issue && result.issue.reason !== 'invalid-keys') return baseGroup;
    return {
      ...baseGroup,
      pages: result.keys.map((key, index) => {
        const pageConfig = pagesConfig[key];
        const dataKey = pageConfig?.dataKey;
        return {
          id: `${baseGroup.id}__${dataKey ?? key}__${index}`,
          componentKey: key,
          templateId: key,
          ...(dataKey ? { dataKey } : {}),
          ...(pageConfig?.hasFlow ? { hasFlow: true } : {}),
        };
      }),
    };
  });

  const initialIds = new Set(initialItems.map((item) => item.id));
  const restoredInitial = rehydrated.filter((item) => initialIds.has(item.id));
  const missingInitial = [...initialIds].some((id) => !restoredInitial.some((item) => item.id === id));
  if (!missingInitial && getTotalPageCount(restoredInitial) !== getTotalPageCount(initialItems)) {
    const additions = rehydrated.filter((item) => !initialIds.has(item.id) && (item.kind !== 'group' || item.id !== (item.templateId ?? item.id)));
    return additions.length ? enforcePageItemPositions([...initialItems, ...additions]) : initialItems;
  }
  return rehydrated;
}
